<script setup lang="ts">
import {computed, onMounted, ref} from 'vue'
import {useRouter} from 'vue-router'
import {useCatalog} from '../stores/catalog'
import {aiDiscover, aiTokens, discover} from '../services/discovery'
import type {AiMatch} from '../services/discovery'
import type {Api, Match, Operation} from '../types'
const store=useCatalog(),router=useRouter(),mode=ref<'match'|'filter'>('match'),query=ref(''),results=ref<Match[]>([]),searched=ref(false),filterStatus=ref('all'),filterTeam=ref('all')
const aiRequirement=ref(''),aiResults=ref<AiMatch[]>([]),aiBusy=ref(false),aiAnalysis=ref(false),aiSelected=ref<Api|null>(null),aiOps=ref<Operation[]>([]),aiCopied=ref(false),aiModeLabel=ref('Local demo scoring')
const filterFields=['OPERATION_ID','API_NAME','NAMED_VALUE','BACKEND','URL_SUFFIX','PATH','METHOD','TEAM','STATUS','VERSION'],filterField=ref('OPERATION_ID'),filterOp=ref('='),filterValue=ref(''),filterJoin=ref<'AND'|'OR'>('AND'),filterRows=ref([{field:'OPERATION_ID',op:'=',value:''}])
const filterExamples=["OPERATION_ID = 'TEST123'","BACKEND = '%ZETA%'","NAMED_VALUE = 'kv-ai-prod/%'","API_NAME = '%Search%' OR API_NAME = '%Embed%'","OPERATION_ID = 'TEST123' AND BACKEND = '%ZETA%'"]
const teams=computed(()=>[...new Set(store.apis.map(a=>a.team))].sort()),visible=computed(()=>results.value.filter(r=>(filterStatus.value==='all'||r.api.status===filterStatus.value)&&(filterTeam.value==='all'||r.api.team===filterTeam.value)))
const aiRecommendation=computed(()=>{const score=aiResults.value[0]?.score??0;return score>=68?'Reuse candidate':score>=35?'Review / possibly extend':'No strong reuse candidate'})
const aiIntent=computed(()=>aiTokens(aiRequirement.value).slice(0,3).join(', ')||'Not identified')
function search(){store.metrics.searches++;results.value=discover(store.apis,query.value,false);searched.value=true}
function sample(q:string){query.value=q;mode.value='match';search()}
function reuse(r:Match){store.recordReuse();router.push({path:'/docs',query:{id:r.api.id}})}
function extend(r:Match){router.push({path:'/create',query:{extend:r.api.id}})}
function exportResults(){const rows=[['API','Version','Score','Backend','Gateway','Owner','Status'],...visible.value.map(x=>[x.api.name,x.api.version,String(x.score),x.api.backend,x.api.suffix,x.api.team,x.api.status])];const csv=rows.map(r=>r.map(v=>'"'+v.replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='integraiq-discovery.csv';a.click();URL.revokeObjectURL(url)}
function aiExplain(m:AiMatch){const q=aiTokens(aiRequirement.value),ops=m.api.ops.filter(o=>aiTokens(o[1]+' '+o[2]).some(t=>q.includes(t))).slice(0,3);return ops.length?ops:m.api.ops.slice(0,2)}
async function runAI(){if(aiRequirement.value.trim().length<12){window.alert('Please enter a little more detail about the business requirement');return}aiBusy.value=true;aiAnalysis.value=false;store.metrics.searches++;try{const endpoint=(import.meta.env.VITE_AI_ENDPOINT||(window.location.protocol.startsWith('http')?'/api/ai':'')).replace(/\/$/,'');if(endpoint){const response=await fetch(endpoint+'/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requirement:aiRequirement.value,catalog:store.apis})});if(!response.ok)throw Error(`AI service returned HTTP ${response.status}`);const data=await response.json() as {matches?:Array<{id:string;score?:number;matched_terms?:string[];gaps?:string[];reason?:string}>};aiModeLabel.value='AI service response';aiResults.value=(data.matches||[]).map(m=>{const api=store.apis.find(a=>a.id===m.id);return api?{api,score:m.score||0,matched:m.matched_terms||[],gaps:m.gaps||[],why:m.reason||'AI relevance match'}:null}).filter((m):m is AiMatch=>Boolean(m))}else{await new Promise(resolve=>setTimeout(resolve,120));aiResults.value=aiDiscover(store.apis,aiRequirement.value)} }catch{aiModeLabel.value='Local demo scoring';aiResults.value=aiDiscover(store.apis,aiRequirement.value)}finally{aiBusy.value=false;aiAnalysis.value=true}}
function openAiReuse(api:Api){aiSelected.value=api;aiOps.value=[['GET','/','','']]}
function addAiOp(){aiOps.value.push(['GET','/','',''])}
function removeAiOp(i:number){aiOps.value.splice(i,1)}
function commitAiOps(){if(!aiSelected.value)return;const add=aiOps.value.filter(o=>o[1].trim());if(!add.length)return;const api=structuredClone(aiSelected.value);api.ops.push(...add);store.updateApi(api);store.recordReuse();aiSelected.value=api;aiOps.value=[]}
function useAiAsIs(api:Api){store.recordReuse();router.push({path:'/docs',query:{id:api.id}})}
async function copyAI(){const text=`Requirement: ${aiRequirement.value}\nCandidates:\n`+aiResults.value.map(r=>`${r.api.name}: ${r.score}%`).join('\n');try{await navigator.clipboard.writeText(text);aiCopied.value=true;setTimeout(()=>aiCopied.value=false,1800)}catch{window.alert('Clipboard unavailable')}}
function draftFromAi(){router.push({path:'/create',query:{requirement:aiRequirement.value}})}
function setFilterExample(value:string){const clauses=[...value.matchAll(/(\w+)\s*(=|LIKE)\s*'([^']*)'/g)].map(m=>({field:m[1],op:m[2],value:m[3]}));if(clauses.length){filterRows.value=clauses;filterJoin.value=value.includes(' OR ')?'OR':'AND';filterField.value=clauses[0].field;filterOp.value=clauses[0].op;filterValue.value=clauses[0].value}}
function addFilter(){if(filterValue.value.trim())filterRows.value.push({field:filterField.value,op:filterOp.value,value:filterValue.value})}
function removeFilter(i:number){filterRows.value.splice(i,1)}
function matchesFilter(api:Api,row:{field:string;op:string;value:string}){const ops=api.ops.map(o=>`${o[0]} ${o[1]} ${o[2]} ${o[3]||''}`).join(' '),values:Record<string,string>={OPERATION_ID:ops,API_NAME:api.name,NAMED_VALUE:api.vault,BACKEND:api.backend,URL_SUFFIX:api.suffix,PATH:ops,METHOD:ops,TEAM:api.team,STATUS:api.status,VERSION:api.version};const actual=(values[row.field]||'').toLowerCase(),expected=row.value.toLowerCase().replace(/%/g,'');return row.op==='='?actual.includes(expected):actual.includes(expected)}
function runFilter(){const active=filterRows.value.filter(r=>r.value.trim());results.value=store.apis.filter(api=>active.length?(filterJoin.value==='OR'?active.some(r=>matchesFilter(api,r)):active.every(r=>matchesFilter(api,r))):true).map(api=>({api,score:100,why:'Advanced catalog filter match'}));searched.value=true;store.metrics.searches++}
onMounted(()=>{const q=sessionStorage.getItem('integraiq-requirement');if(q){sessionStorage.removeItem('integraiq-requirement');aiRequirement.value=q;runAI()}})
</script>
<template>
<h1>API Discovery</h1><p class="sub">Find an existing API before creating another integration.</p>
<section class="card ai-card"><div class="ai-head"><span class="ai-orb">✦</span><div><h2 style="margin:0">Search by business requirement</h2><span class="mu small">Describe the capability in plain English instead of knowing an API name or URL.</span></div><span class="ai-chip">Semantic discovery</span></div><label for="ai-requirement">Business requirement</label><textarea id="ai-requirement" v-model="aiRequirement" rows="3" placeholder="e.g. Generate vector embeddings for text so similar content can be found."/><div class="ai-actions"><button class="btn" :disabled="aiBusy" @click="runAI">✦ Understand &amp; find APIs</button><button class="btn ghost sm" @click="aiRequirement='Generate vector embeddings for text and documents so similar content can be found.'">Try embeddings example</button><button class="btn ghost sm" @click="aiRequirement='Summarize long documents and retrieve the summary for a submitted document.'">Try summarization example</button></div><p class="ai-note">The current standalone demo uses explainable local relevance scoring. Connect the optional backend endpoint for Azure OpenAI and embedding-based semantic search.</p><div v-if="aiBusy" class="ai-loading">Understanding requirement and searching the API catalog…</div><div v-if="aiAnalysis&&!aiBusy"><div class="ai-result"><div class="ai-result-top"><b>Requirement analysis</b><span class="ai-chip">{{aiModeLabel}}</span></div><div class="ai-grid"><div class="ai-kv"><b>Intent</b>{{aiIntent}}</div><div class="ai-kv"><b>Catalog candidates</b>{{aiResults.length}}</div><div class="ai-kv"><b>Recommendation</b>{{aiRecommendation}}</div></div><p>{{aiRecommendation==='Reuse candidate'?'An existing API appears to cover important parts of this requirement. Validate operation-level coverage with the owning team.':aiRecommendation==='Review / possibly extend'?'Some related capabilities exist. Check missing operations and ownership before deciding.':'No sufficiently relevant API was found in this sample catalog. A new API design may be appropriate after confirming the search scope.'}}</p></div><div v-if="!aiResults.length" class="ai-warn">No relevant API was identified in the current sample catalog. Confirm that the catalog contains the relevant domain APIs before creating a new one.</div><div v-for="(r,index) in aiResults" :key="r.api.id" class="ai-result"><div class="ai-result-top"><div><b>{{r.api.name}}</b> <span class="ver">{{r.api.version}}</span> <span v-if="index===0" class="ai-chip">Top candidate</span></div><div class="ai-score">{{r.score}}%</div></div><p class="mu small">{{r.api.desc}}</p><p class="small"><b>Why relevant:</b> {{r.why}}</p><p class="small"><b>Potential gaps to validate:</b> {{r.gaps.length?r.gaps.join(', '):'No obvious keyword gaps; confirm actual business and data coverage.'}}</p><p class="small"><b>Related operations:</b> {{aiExplain(r).map(o=>o[0]+' '+o[1]+' – '+o[2]).join(' · ')}}</p><div class="ai-actions"><button class="btn sm" @click="router.push({path:'/docs',query:{id:r.api.id}})">View API details</button><button class="btn ghost sm" @click="openAiReuse(r.api)">Reuse / extend</button></div><div v-if="aiSelected?.id===r.api.id" class="rpanel"><h3>Reuse {{aiSelected.name}}</h3><p class="mu">It has {{aiSelected.ops.length}} operations today. Need something it doesn’t expose yet? Add operations below; the change is proposed as a simulated pull request for {{aiSelected.team}} to review.</p><div v-for="(op,i) in aiOps" :key="i" class="row mt"><select v-model="op[0]"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><input v-model="op[1]" placeholder="/path"/><input v-model="op[2]" placeholder="Summary"/><button class="btn ghost sm" @click="removeAiOp(i)">×</button></div><button class="btn ghost sm mt" @click="addAiOp">+ Add operation</button><div class="ai-actions"><button class="btn" @click="commitAiOps">Add operations &amp; open pull request</button><button class="btn ghost" @click="useAiAsIs(aiSelected)">Use as is, no changes</button></div></div></div><div class="ai-result"><b>Next recommended action</b><p class="mu small">{{aiRecommendation==='No strong reuse candidate'?'Draft a new API proposal, then complete backend, owning team and security details.':'Review the top candidate and confirm its operation and data coverage.'}}</p><div class="ai-actions"><button class="btn" @click="draftFromAi">✦ Draft API design from requirement</button><button class="btn ghost sm" @click="copyAI">{{aiCopied?'Copied':'Copy analysis'}}</button></div></div></div></section>
<div class="seg" role="tablist"><button :class="{on:mode==='match'}" @click="mode='match'">Reuse check</button><button :class="{on:mode==='filter'}" @click="mode='filter'">Advanced filter</button></div>
<div v-if="mode==='match'" class="card searchbox"><label for="query">API name, backend URL or gateway suffix</label><div class="row"><input id="query" v-model="query" placeholder="https://ml.internal.contoso.com/inference" @keydown.enter="search"><button class="btn" @click="search">Check</button></div><p class="ai-note">Endpoint and catalog metadata are matched locally.</p><div class="try">Try: <button class="lnk" @click="sample('Embeddings API')">Embeddings API</button> · <button class="lnk" @click="sample('https://ml.internal.contoso.com/inference')">Inference URL</button> · <button class="lnk" @click="sample('fraud scoring')">Fraud scoring</button></div></div>
<div v-else class="card searchbox"><label>Advanced catalog filter</label><div v-for="(row,i) in filterRows" :key="i" class="row mt"><select v-model="row.field"><option v-for="field in filterFields" :key="field">{{field}}</option></select><select v-model="row.op"><option>=</option><option>LIKE</option></select><input v-model="row.value" placeholder="Value"/><button class="btn ghost sm" @click="removeFilter(i)">×</button></div><div class="ai-actions"><button class="btn ghost sm" @click="addFilter">+ Add filter</button><label style="display:flex;align-items:center;gap:6px;margin:0">Join<select v-model="filterJoin" style="width:auto"><option>AND</option><option>OR</option></select></label><button class="btn" @click="runFilter">Run filter</button></div><div class="try">Examples: <button v-for="example in filterExamples" :key="example" class="lnk" @click="setFilterExample(example)">{{example}}</button></div></div>
<div v-if="searched"><div class="toolbar"><div class="res-h"><h2 style="margin:0">{{visible.length}} candidate APIs</h2><span class="pill">{{results[0]?.score??0}}% top match</span></div><button class="btn ghost sm" v-if="visible.length" @click="exportResults">Export CSV</button></div><div class="row" style="margin-bottom:14px"><div><label>Status</label><select v-model="filterStatus"><option value="all">All statuses</option><option>active</option><option>beta</option><option>deprecated</option></select></div><div><label>Team</label><select v-model="filterTeam"><option value="all">All teams</option><option v-for="t in teams" :key="t">{{t}}</option></select></div></div><div v-if="!visible.length" class="card empty">No matching APIs in this demo catalog. Review the search scope before proposing a new one.<div class="actions" style="justify-content:center"><button class="btn" @click="router.push('/create')">Create API draft</button></div></div><div v-for="r in visible" :key="r.api.id" class="card found"><div class="f-top"><span class="f-ic">⚡</span><div class="f-ti"><span class="tag" :class="'st-'+r.api.status">{{r.api.status}}</span><h2>{{r.api.name}} <span class="ver">{{r.api.version}}</span></h2><p>{{r.api.desc}}</p></div><div class="f-cnt"><b>{{r.score}}%</b><span>Match score</span></div></div><div class="f-meta"><div><i>Backend</i><code>{{r.api.backend}}</code></div><div><i>Gateway</i><code>{{r.api.suffix}}</code></div><div><i>Owning team</i>{{r.api.team}}</div></div><div class="f-rec" :class="r.score>=90?'':r.score>=60?'rv':'warn'"><b>{{r.score>=90?'Strong reuse match':r.score>=60?'Review for reuse':'Possible overlap'}}</b><p>{{r.why}}. Confirm coverage with the owning team before deciding.</p></div><div class="f-ops"><div v-for="op in r.api.ops.slice(0,4)" :key="op[0]+op[1]" class="f-op"><span class="m" :class="op[0]">{{op[0]}}</span><code>{{op[1]}}</code><span>{{op[2]}}</span></div></div><div class="f-act"><button class="btn" @click="reuse(r)">Reuse / view docs</button><button class="btn ghost" @click="extend(r)">Extend API</button></div></div></div>
</template>
